import{_ as a,o as e,c as i,a3 as l}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"30 分鐘通關","description":"從零到 MiniTavern 收到本地模型第一條回覆：選 Ollama 或 LM Studio、裝模型、局域網連 App，約 30 分鐘。","frontmatter":{"title":"30 分鐘通關","description":"從零到 MiniTavern 收到本地模型第一條回覆：選 Ollama 或 LM Studio、裝模型、局域網連 App，約 30 分鐘。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"30 分鐘通關 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"從零到 MiniTavern 收到本地模型第一條回覆：選 Ollama 或 LM Studio、裝模型、局域網連 App，約 30 分鐘。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/quickstart"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/quickstart"}]]},"headers":[],"relativePath":"zh-TW/quickstart.md","filePath":"zh-TW/quickstart.md","lastUpdated":1787224147000}'),r={name:"zh-TW/quickstart.md"};function o(n,t,s,d,p,h){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="_30-分鐘通關" tabindex="-1">30 分鐘通關 <a class="header-anchor" href="#_30-分鐘通關" aria-label="Permalink to &quot;30 分鐘通關&quot;">​</a></h1><p>目標：從零到在 MiniTavern 裡收到本地模型的第一條回覆。</p><table tabindex="0"><thead><tr><th>步驟</th><th>大約用時</th><th>做什麼</th></tr></thead><tbody><tr><td>1</td><td>0–5 min</td><td>選工具：Ollama 或 LM Studio</td></tr><tr><td>2</td><td>5–15 min</td><td>安裝並下載一個小模型</td></tr><tr><td>3</td><td>15–20 min</td><td>開啟局域網 / Local Server</td></tr><tr><td>4</td><td>20–25 min</td><td>查電腦局域網 IP</td></tr><tr><td>5</td><td>25–30 min</td><td>在 MiniTavern 新建連接並測連</td></tr></tbody></table><hr><h2 id="step-1-選工具" tabindex="-1">Step 1：選工具 <a class="header-anchor" href="#step-1-選工具" aria-label="Permalink to &quot;Step 1：選工具&quot;">​</a></h2><ul><li><strong>想最快</strong>：選 <a href="./ollama/install">Ollama</a> 或 <a href="./lmstudio/install">LM Studio</a></li><li><strong>角色扮演向</strong>：可後續換 <a href="./koboldcpp/install">KoboldCPP</a></li><li><strong>已有 GGUF</strong>：可用 <a href="./llamacpp/install">llama.cpp</a></li></ul><p>完整對比見 <a href="./local/tools">工具總覽</a>。下面以 <strong>Ollama</strong> 為例寫通關步驟；其它工具把「拉模型 / 開服務」換成對應章節即可，第 5 步相同。</p><hr><h2 id="step-2-安裝並拉一個小模型" tabindex="-1">Step 2：安裝並拉一個小模型 <a class="header-anchor" href="#step-2-安裝並拉一個小模型" aria-label="Permalink to &quot;Step 2：安裝並拉一個小模型&quot;">​</a></h2><ol><li>按 <a href="./ollama/install">Ollama 安裝</a> 裝好。</li><li>打開終端，執行（示例模型，體積相對小，適合驗證通路）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><ol start="3"><li>確認本機可用：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><p>能對話後輸入 <code>/bye</code> 退出即可。更多模型選擇見 <a href="./ollama/models">下載與選擇模型</a>。</p><hr><h2 id="step-3-開啟局域網訪問" tabindex="-1">Step 3：開啟局域網訪問 <a class="header-anchor" href="#step-3-開啟局域網訪問" aria-label="Permalink to &quot;Step 3：開啟局域網訪問&quot;">​</a></h2><p>按 <a href="./ollama/lan">開啟局域網訪問</a> 設置 <code>OLLAMA_HOST=0.0.0.0</code>，並放行防火牆端口 <strong>11434</strong>。</p><p>完成後，在<strong>電腦本機</strong>瀏覽器訪問（應有響應，不一定是漂亮網頁）：</p><p><code>http://127.0.0.1:11434</code></p><hr><h2 id="step-4-查電腦局域網-ip" tabindex="-1">Step 4：查電腦局域網 IP <a class="header-anchor" href="#step-4-查電腦局域網-ip" aria-label="Permalink to &quot;Step 4：查電腦局域網 IP&quot;">​</a></h2><ul><li><strong>Windows</strong>：<code>Win + R</code> → <code>cmd</code> → 輸入 <code>ipconfig</code>，找「無線局域網適配器」下的 <strong>IPv4 地址</strong>（形如 <code>192.168.x.x</code>）。</li><li><strong>macOS</strong>：系統設置 → 網絡 → 當前 Wi‑Fi → 詳情裡的 IP；或終端執行 <code>ipconfig getifaddr en0</code>。</li></ul><p>記下這個 IP，後面記作 <code>YOUR_PC_IP</code>。</p><hr><h2 id="step-5-在-minitavern-裡配置" tabindex="-1">Step 5：在 MiniTavern 裡配置 <a class="header-anchor" href="#step-5-在-minitavern-裡配置" aria-label="Permalink to &quot;Step 5：在 MiniTavern 裡配置&quot;">​</a></h2><ol><li>打開 App → <strong>設置 → 模型 → 模型連接 → 新建</strong>。</li><li>平臺選 <strong>自定義 / OpenAI 兼容</strong>（以 App 內實際選項名為準）。</li><li>填寫：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>示例（Ollama）</th></tr></thead><tbody><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:11434/v1</code></td></tr><tr><td>API Key</td><td>可留空或填任意佔位（本地通常不校驗）</td></tr><tr><td>模型名</td><td><code>llama3.2:3b</code>（與 <code>ollama list</code> 一致）</td></tr></tbody></table><ol start="4"><li>保存並 <strong>測連</strong>；成功後設為默認，導入角色卡開聊。</li></ol><p>完整界面說明見 <a href="./connect-app/minitavern">在 MiniTavern 中配置</a>。</p><hr><h2 id="失敗了" tabindex="-1">失敗了？ <a class="header-anchor" href="#失敗了" aria-label="Permalink to &quot;失敗了？&quot;">​</a></h2><ul><li>測連失敗、超時、空白回覆 → 打開 <a href="./troubleshoot">排錯對照表</a></li><li>最常見錯誤：<strong>Base URL 寫成了 <code>localhost</code></strong>，或手機與電腦不在同一 Wi‑Fi</li></ul>',32)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
